      "trecho_corrigido": "function getCodingChallengeFromFileContent (source: string, challengeKey: string) {\n  const escapedChallengeKey = challengeKey.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')\n  const snippets = source.match(`[/#]{0,2} vuln-code-snippet start.*${escapedChallengeKey}([^])*vuln-code-snippet end.*${escapedChallengeKey}`)"
